        """.trimIndent().lines()
        rows.forEachIndexed { index,row ->
            val cells=row.split('|');val value=Double.fromBits(cells[0].toULong(16).toLong())
            assertEquals(cells[1],jsNumberToString(value),"Case $index string")
            assertEquals(cells[2],jsNumberToPrecision6(value),"Case $index precision")
            listOf(0,1,2,6,10).forEachIndexed { column,precision -> assertEquals(cells[column+3],jsNumberToFixed(value,precision),"Case $index fixed $precision") }
            val rounded=jsMathRound(value)
            assertEquals(cells[8],jsNumberToString(rounded),"Case $index round")
            assertEquals(cells[9].toBoolean(),rounded.toBits()==(-0.0).toBits(),"Case $index round sign")
        }
