    @Test
    fun onlySourceSupportedDisplayPrecisionIsAdmitted() {
        assertFailsWith<IllegalArgumentException> { jsNumberToFixed(1.0,-1) }
        assertFailsWith<IllegalArgumentException> { jsNumberToFixed(Double.NaN,11) }
        for(precision in 0..10) assertEquals(if(precision==0) "0" else "0."+"0".repeat(precision),jsNumberToFixed(-0.0,precision))
    }
